-- 通讯基站统计 数据（数据源：金山文档《寺家庄镇2026918小区通讯基站情况统计表》）
-- 仅保留寺家庄镇：金山 18 条 + 补充 0 条 = 18 条
DELETE FROM `base_station`;
ALTER TABLE `base_station` AUTO_INCREMENT = 1;


-- 按小区名称自动关联本系统小区
UPDATE `base_station` s JOIN `community` c ON s.`community_name` = c.`name`
   SET s.`community_id` = c.`id`;

-- 别名关联（统计表与系统小区名称叫法不同）
UPDATE `base_station` s JOIN `community` c ON c.`name`='万和华府' SET s.`community_id` = c.`id` WHERE s.`community_name`='万合华府';
UPDATE `base_station` s JOIN `community` c ON c.`name`='柠檬小镇' SET s.`community_id` = c.`id` WHERE s.`community_name`='柠檬小区';
UPDATE `base_station` s JOIN `community` c ON c.`name`='长久广场' SET s.`community_id` = c.`id` WHERE s.`community_name`='长九广场';
UPDATE `base_station` s JOIN `community` c ON c.`name`='四季阳光' SET s.`community_id` = c.`id` WHERE s.`community_name`='四季阳光城';
